const figures={
  motion:['mean.jpg','AV and HV distributions of event-level motion indicators.','Complete-feature events. Bars show density histograms; curves show smoothed histogram densities.'],
  proximity:['PET-dmin-time.jpg','PET, minimum trajectory distance and arrival-time gap by target road-user type.','Complete-feature events. Boxes show the interquartile range, center lines the median, and whiskers the 5th–95th percentiles. Connected black dots indicate means.'],
  patterns:['Features.jpg','Normalized indicator profiles for five intersection and four proximity interaction patterns.','Within-pattern medians are divided by the largest pattern median for each indicator and interaction type. Radius represents relative magnitude, not an overall behavioral score.'],
  within:['Comparison of event-level indicators.jpg','Within-pattern AV and HV comparisons of motion response and proximity indicators.','Complete-feature events pooled across all three target types. Boxes show the interquartile range, white lines the median, and whiskers the 5th–95th percentiles.'],
  events:['Data.jpg','Target road-user composition and hourly counts of extracted interaction events.','All extracted events. Bars show total event counts by target type; lines show hourly event counts.']
};
const tabs=[...document.querySelectorAll('[role=tab]')];
const sectionLinks=[...document.querySelectorAll('.navigation > div a')];
const sectionObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){sectionLinks.forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}}},{rootMargin:'-15% 0px -65% 0px'});
document.querySelectorAll('main > section').forEach(section=>sectionObserver.observe(section));
function chooseTab(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1;});const [file,alt,caption]=figures[tab.dataset.figure];const url='static/images/'+file;document.querySelector('#result-image').src=url;document.querySelector('#result-image').alt=alt;document.querySelector('#result-link').href=url;document.querySelector('#result-link').dataset.caption=caption;document.querySelector('#result-caption').textContent=caption;document.querySelector('#result-panel').setAttribute('aria-labelledby',tab.id);}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>chooseTab(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();chooseTab(tabs[next]);}});});
const data={
 I:{motor:{n:[281,17980],av:[18.86,21.71,13.52,32.38,13.52],hv:[17.81,20.99,14.54,30.57,16.08],diff:[1.05,.72,-1.02,1.82,-2.56]},pedestrian:{n:[25,1936],av:[8,36,0,4,52],hv:[5.27,31.20,5.84,6.10,51.60],diff:[2.73,4.80,-5.84,-2.10,.40]},nonmotor:{n:[189,7317],av:[27.51,22.22,12.17,20.11,17.99],hv:[27.52,23.34,15.50,6.55,27.09],diff:[-.01,-1.12,-3.33,13.56,-9.10]}},
 P:{motor:{n:[1078,65215],av:[21.52,27.55,28.85,22.08],hv:[18.53,25.85,28.09,27.52],diff:[2.99,1.70,.76,-5.45]},pedestrian:{n:[85,4803],av:[17.65,48.24,30.59,3.53],hv:[27.88,41.81,28.48,1.83],diff:[-10.23,6.43,2.11,1.70]},nonmotor:{n:[401,14934],av:[26.93,41.90,18.70,12.47],hv:[27.53,44.82,21.38,6.27],diff:[-.60,-2.92,-2.68,6.19]}}
};
let kind='I';
const target=document.querySelector('#target');
function renderShares(){const d=data[kind][target.value];document.querySelector('#sample-size').textContent=`Complete-feature events: AV n = ${d.n[0].toLocaleString('en-US')} | HV n = ${d.n[1].toLocaleString('en-US')}`;document.querySelector('#share-chart').innerHTML=d.av.map((v,i)=>`<div class="chart-row"><span class="pattern-label">${kind}-${i+1}</span><div class="bars"><div class="bar-line"><span class="bar" style="width:${v/60*80}%"></span><span class="bar-number">${v.toFixed(2)}%</span></div><div class="bar-line"><span class="bar hv" style="width:${d.hv[i]/60*80}%"></span><span class="bar-number">${d.hv[i].toFixed(2)}%</span></div></div><span class="difference">${d.diff[i]>0?'+':''}${d.diff[i].toFixed(2)} pp<small>AV minus HV</small></span></div>`).join('');let i=d.diff.reduce((best,x,j)=>Math.abs(x)>Math.abs(d.diff[best])?j:best,0);document.querySelector('#share-insight').textContent=kind==='I'&&target.value==='nonmotor'?'AVs have a 13.56 pp higher I-4 share and a 9.10 pp lower I-5 share than HVs.':`The largest absolute share difference in this group is ${kind}-${i+1}: ${Math.abs(d.diff[i]).toFixed(2)} pp ${d.diff[i]>0?'higher':'lower'} for AVs than HVs.`;}
document.querySelectorAll('[data-kind]').forEach(b=>b.addEventListener('click',()=>{kind=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));renderShares();}));target.addEventListener('change',renderShares);renderShares();
const viewer=document.querySelector('#viewer');document.querySelectorAll('a.zoom').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const img=a.querySelector('img');document.querySelector('#viewer-image').src=a.href;document.querySelector('#viewer-image').alt=img.alt;document.querySelector('#viewer-caption').textContent=a.dataset.caption||img.alt;viewer.showModal();}));viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close();}});
